export interface ImportedLessonRecord {
  id: string;
  sourceSheet: string;
  sourceRow: number;
  teacherSourceName: string;
  teacherMatchStatus: ImportedTeacher["matchStatus"];
  className: string;
  groupName: string;
  subject: string;
  duration: string;
  periodsPerWeek: number | null;
  availableRooms: string;
  cycle: string;
  sharedTeachers: string;
  rooms: string;
  raw: Record<string, CellValue>;
  weekday: string | null;
  period: number | null;
}

export interface ImportedReferenceRow {
  sourceSheet: string;
  sourceRow: number;
  values: Record<string, CellValue>;
}

export interface WorkbookImportResult {
  schemaVersion: 1;
  sourceSheets: string[];
  teachers: ImportedTeacher[];
  unmatchedTeacherNames: string[];
  ambiguousTeacherNames: string[];
  unassignedRecords: ImportedLessonRecord[];
  referenceData: Record<string, ImportedReferenceRow[]>;
  placements: ImportedLessonRecord[];
  hasWeeklyPlacements: boolean;
  warnings: string[];
  validation: { valid:boolean; errors:string[]; warnings:string[] };
  totals: {
    importedTeacherRows: number;
    importedLessonRecords: number;
    referenceRows: number;
    placementRows: number;
  };
}

const SHEET_ALIASES = {
  lessons: ["الحصص", "الحصة", "الدروس"],
  classes: ["الفصول", "الشعب", "الصفوف"],
  rooms: ["الغرف الدراسية", "الغرف", "القاعات"],
  subjects: ["المواد", "المادة"],
  teachers: ["المعلمون", "المعلمين", "المعلم"],
  classContracts: ["العقود الفصول", "عقود الفصول", "عقود الشعب"],
  contracts: ["العقد", "العقود"],
} as const;

function clean(value: CellValue): string {
  if (value === null || value === undefined) return "";
  return String(value).replace(/\u00a0/g, " ").replace(/[\u200e\u200f\u202a-\u202e]/g, "").trim();
}

export function normalizeArabicName(value: CellValue): string {
  return clean(value)
    .normalize("NFKC")
    .replace(/[\u064b-\u065f\u0670\u0640]/g, "")
    .replace(/[أإآٱ]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ؤ/g, "و")
    .replace(/ئ/g, "ي")
    .replace(/ة/g, "ه")
    .replace(/[ـ.,،؛:()\[\]{}]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLocaleLowerCase("ar");
}


function normalizeTeacherAliasKey(value: CellValue): string {
  return normalizeArabicName(value).replace(/\s+/g, "");
}

/** Matching-only tokens: keep the original source spelling in the import record. */
function teacherNameTokens(value: CellValue): string[] {
  return normalizeArabicName(value)
    .replace(/عبدال/g, "عبد ال")
    .replace(/(^|\s)(?:بن|ابن)(?=\s|$)/g, "$1")
    .split(/\s+/)
    .filter(Boolean);
}

function isOrderedSubsequence(needle: string[], haystack: string[]): boolean {
  if (!needle.length) return false;
  let index = 0;
  for (const token of haystack) {
    if (token === needle[index]) index++;
    if (index === needle.length) return true;
  }
  return false;
}

/**
 * The timetable workbook contains both a detailed name and a short alias,
 * while the live system commonly stores first name + family name. Prefer
 * evidence from the detailed name; use the alias as a strong fallback.
 */
function scoreTeacherCandidate(source: ImportedTeacher, candidate: SystemTeacher): number {
  const fullKey = normalizeArabicName(source.sourceName);
  const candidateKey = normalizeArabicName(candidate.name);
  if (fullKey && fullKey === candidateKey) return 120;

  const fullTokens = teacherNameTokens(source.sourceName);
  const candidateTokens = teacherNameTokens(candidate.name);
  const aliasExact = source.aliases.some((alias) => normalizeArabicName(alias) === candidateKey);
  if (!fullTokens.length || !candidateTokens.length) return aliasExact ? 82 : 0;

  let score = 0;
  if (fullTokens[0] === candidateTokens[0]) score += 35;
  if (fullTokens[fullTokens.length - 1] === candidateTokens[candidateTokens.length - 1]) score += 35;

  if (isOrderedSubsequence(candidateTokens, fullTokens)) {
    score += 20 + Math.max(0, candidateTokens.length - 2) * 4;
  }
  const isPrefix = candidateTokens.every((token, index) => fullTokens[index] === token);
  if (isPrefix) score += 25;
  const interiorMatches = candidateTokens.slice(1, -1)
    .filter((token) => fullTokens.includes(token)).length;
  score += interiorMatches * 5;

  // Typing/OCR tolerance is a supporting signal, never identity proof by itself.
  const compactSource = fullKey.replace(/\s+/g, "");
  const compactCandidate = candidateKey.replace(/\s+/g, "");
  const editDistance = (a: string, b: string): number => {
    const row = Array.from({ length: b.length + 1 }, (_, i) => i);
    for (let i = 1; i <= a.length; i++) {
      let diagonal = row[0];
      row[0] = i;
      for (let j = 1; j <= b.length; j++) {
        const previous = row[j];
        row[j] = Math.min(row[j] + 1, row[j - 1] + 1, diagonal + (a[i - 1] === b[j - 1] ? 0 : 1));
        diagonal = previous;
      }
    }
    return row[b.length];
  };
  if (compactSource && compactCandidate) {
    const similarity = 1 - editDistance(compactSource, compactCandidate) /
      Math.max(compactSource.length, compactCandidate.length, 1);
    if (similarity >= 0.72) score += Math.round(similarity * 55);
  }
  if (aliasExact) score = Math.max(score, 82);
  return score;
}
/**
 * Explicit identity confirmations supplied by the school.
 * Keys are detailed workbook teacher names; values are existing system teacher names.
 * Short aliases are deliberately not used as keys because they may be shared.
 */
const CONFIRMED_TEACHER_LINKS: Record<string, string> = {
  [normalizeTeacherAliasKey("س فيزياء")]: normalizeArabicName("محمد البشير"),
  [normalizeArabicName("محمد جمعة ناصر السعدي")]: normalizeArabicName("محمد جمعة السعدي"),
  [normalizeArabicName("محمد عبدالله حمود السعدي")]: normalizeArabicName("محمد عبدالله السعدي"),
};

/** Reuse the reviewed workbook identity-matching rules for pasted timetable day imports. */
export function matchSystemTeacherName(sourceName: string, systemTeachers: SystemTeacher[]): {
  teacherName: string | null;
  matchStatus: "matched" | "unmatched" | "ambiguous";
} {
  const source: ImportedTeacher = {
    sourceName,
    normalizedName: normalizeArabicName(sourceName),
    matchedTeacherId: null,
    matchedTeacherName: null,
    matchStatus: "unmatched",
    aliases: [sourceName],
    teacherPeriodNotes: [],
    teacherPeriodNotesRaw: "",
    teacherPeriodNotesWarnings: [],
    records: [],
  };
  const resolved = resolveSystemTeacher(source, systemTeachers);
  return {
    teacherName: resolved.teacher?.name ?? null,
    matchStatus: resolved.teacher ? "matched" : resolved.ambiguous ? "ambiguous" : "unmatched",
  };
}

function resolveSystemTeacher(
  source: ImportedTeacher,
  systemTeachers: SystemTeacher[],
): { teacher: SystemTeacher | null; ambiguous: boolean } {
  const confirmedTarget = CONFIRMED_TEACHER_LINKS[normalizeTeacherAliasKey(source.sourceName)];
  if (confirmedTarget) {
    const confirmedMatches = systemTeachers.filter(
      (teacher) => normalizeArabicName(teacher.name) === confirmedTarget,
    );
    if (confirmedMatches.length === 1) return { teacher: confirmedMatches[0], ambiguous: false };
    // When the confirmed account is present, use it. If this particular school directory
    // does not contain that target, fall through to confidence-scored detailed-name matching.
    // This supports the same detailed source label in separate directories without guessing.
    if (confirmedMatches.length > 1) return { teacher: null, ambiguous: true };
  }

  const ranked = systemTeachers
    .map((teacher) => ({ teacher, score: scoreTeacherCandidate(source, teacher) }))
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score || a.teacher.name.localeCompare(b.teacher.name, "ar"));

  if (!ranked.length || ranked[0].score < 78) return { teacher: null, ambiguous: false };
  const secondScore = ranked[1]?.score ?? -1;
  if (secondScore >= 78 && ranked[0].score - secondScore < 5) {
    return { teacher: null, ambiguous: true };
  }
  return { teacher: ranked[0].teacher, ambiguous: false };
}

function normalizeSubjectName(value: CellValue): string {
  const source = clean(value);
  const key = normalizeArabicName(source);
  if (!key) return "";
  if (["حصه دينيه", "دينيه"].includes(key)) return "تربية إسلامية";
  if (["عربي", "لغه عربيه", "اللغه العربيه"].includes(key)) return "اللغة العربية";
  if (["انجليزي", "انجليزيه", "لغه انجليزيه", "اللغه الانجليزيه"].includes(key)) return "اللغة الإنجليزية";
  if (["رياضيات", "الرياضيات"].includes(key)) return "الرياضيات";
  if (key === "اجتماع الاسلاميه" || key === "اجتماع التربيه الاسلاميه") return "اجتماع التربية الإسلامية";
  return source;
}

function normalizeHeader(value: CellValue): string {
  return normalizeArabicName(value).replace(/\s+/g, "");
}

function firstValue(row: Record<string, CellValue>, candidates: string[]): string {
  const wanted = new Set(candidates.map(normalizeHeader));
  for (const [key, value] of Object.entries(row)) {
    if (wanted.has(normalizeHeader(key))) {
      const text = clean(value);
      if (text) return text;
    }
  }
  return "";
}

function findHeaderRow(rows: CellValue[][]): number {
  for (let i = 0; i < Math.min(rows.length, 12); i++) {
    const values = rows[i] || [];
    const filled = values.filter((v) => clean(v)).length;
    if (filled >= 2) return i;
  }
  return -1;
}

function rowsToObjects(rows: CellValue[][]): Array<{ rowNumber: number; values: Record<string, CellValue> }> {
  const headerIndex = findHeaderRow(rows);
  if (headerIndex < 0) return [];
  const headers = (rows[headerIndex] || []).map((v, i) => clean(v) || `عمود ${i + 1}`);
  const output: Array<{ rowNumber: number; values: Record<string, CellValue> }> = [];
  for (let i = headerIndex + 1; i < rows.length; i++) {
    const cells = rows[i] || [];
    if (!cells.some((v) => clean(v))) continue;
    const values: Record<string, CellValue> = {};
    headers.forEach((header, index) => {
      if (header) values[header] = cells[index] ?? null;
    });
    output.push({ rowNumber: i + 1, values });
  }
  return output;
}

function findSheet(sheets: WorkbookRows, aliases: readonly string[]): string | null {
  const wanted = new Set(aliases.map(normalizeArabicName));
  return Object.keys(sheets).find((name) => wanted.has(normalizeArabicName(name))) || null;
}

function valueByHeader(row: Record<string, CellValue>, candidates: string[]): CellValue {
  const wanted = new Set(candidates.map(normalizeHeader));
  for (const [key, value] of Object.entries(row)) {
    if (wanted.has(normalizeHeader(key))) return value;
  }
  return null;
}

function parseCount(value: CellValue): number | null {
  const text = clean(value).replace(/[٠-٩]/g, (d) => String("٠١٢٣٤٥٦٧٨٩".indexOf(d))).replace(",", ".");
  if (!text) return null;
  const match = text.match(/-?\d+(?:\.\d+)?/);
  if (!match) return null;
  const number = Number(match[0]);
  return Number.isFinite(number) && number >= 0 ? number : null;
}

const SCHOOL_WEEKDAYS = ["الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس"] as const;

function normalizeSchoolWeekday(value: CellValue): string | null {
  const key = normalizeArabicName(value).replace(/^يوم\s*/, "").replace(/\s+/g, "");
  const aliases: Record<string,string> = {
    "الاحد":"الأحد","الاثنين":"الاثنين","الثلاثاء":"الثلاثاء","الاربعاء":"الأربعاء","الخميس":"الخميس",
    "sunday":"الأحد","sun":"الأحد","monday":"الاثنين","mon":"الاثنين",
    "tuesday":"الثلاثاء","tue":"الثلاثاء","wednesday":"الأربعاء","wed":"الأربعاء",
    "thursday":"الخميس","thu":"الخميس",
  };
  return aliases[key] || null;
}

/**
 * Parse day/period references in the teacher sheet's التفريغ field without
 * assigning a meaning such as free, busy, or unavailable. A separate teacher
 * clarification exists for a specific record, but the field's general semantics
 * conflict with other explicit daily teaching records and must remain unconfirmed.
 * Empty or malformed text is never expanded into any schedule state.
 */
export function parseTeacherPeriodNotes(value: CellValue): {
  periods: Array<{ weekday: string; period: number }>;
  warnings: string[];
} {
  const raw = clean(value);
  const periods: Array<{ weekday: string; period: number }> = [];
  const warnings: string[] = [];
  if (!raw) return { periods, warnings };
  const seen = new Set<string>();
  for (const part of raw.split(/[;؛]/).map((item) => item.trim()).filter(Boolean)) {
    const colon = part.indexOf(":");
    if (colon < 0) {
      warnings.push(part);
      continue;
    }
    const dayText = part.slice(0, colon).trim();
    const periodText = part.slice(colon + 1).replace(/[٠-٩]/g, (digit) => String("٠١٢٣٤٥٦٧٨٩".indexOf(digit)));
    const dayRange = dayText.split(/\s*[-–—]\s*/).map((day) => normalizeArabicName(day));
    const dayStart = SCHOOL_WEEKDAYS.findIndex((day) => normalizeArabicName(day) === dayRange[0]);
    const dayEnd = dayRange.length === 1
      ? dayStart
      : SCHOOL_WEEKDAYS.findIndex((day) => normalizeArabicName(day) === dayRange[1]);
    if (dayStart < 0 || dayEnd < dayStart) {
      warnings.push(part);
      continue;
    }
    const selectedDays = SCHOOL_WEEKDAYS.slice(dayStart, dayEnd + 1);
    const selectedPeriods: number[] = [];
    for (const token of periodText.split(/[,،]/).map((item) => item.trim()).filter(Boolean)) {
      const match = token.match(/^(\d+)\s*(?:[-–—]\s*(\d+))?$/);
      if (!match) {
        warnings.push(part);
        continue;
      }
      const first = Number(match[1]);
      const last = Number(match[2] || match[1]);
      if (first < 1 || last > 7 || last < first) {
        warnings.push(part);
        continue;
      }
      for (let period = first; period <= last; period++) selectedPeriods.push(period);
    }
    for (const weekday of selectedDays) {
      for (const period of selectedPeriods) {
        const key = weekday + ":" + period;
        if (!seen.has(key)) {
          seen.add(key);
          periods.push({ weekday, period });
        }
      }
    }
  }
  return { periods, warnings: Array.from(new Set(warnings)) };
}

function buildTeacherDirectory(
  rows: Array<{ rowNumber: number; values: Record<string, CellValue> }>,
  systemTeachers: SystemTeacher[],
): { teachers: ImportedTeacher[]; aliasMap: Map<string, Set<string>> } {
  const byId = new Map(systemTeachers.map((t) => [String(t.id ?? t.name), t]));
  const aliasMap = new Map<string, Set<string>>();
  const imported = new Map<string, ImportedTeacher>();

  for (const item of rows) {
    const name = firstValue(item.values, ["الاسم", "الإسم", "اسم"]);
    if (!name) continue;
    const shortName = firstValue(item.values, ["الاختصار", "الإختصار", "الاسم المختصر"]);
    const key = normalizeArabicName(name);
    if (!key) continue;
    const aliases = [name, shortName].filter(Boolean);
    const freeText = firstValue(item.values, ["التفريغ"]);
    const parsedFree = parseTeacherPeriodNotes(freeText);
    const current = imported.get(key) || {
      sourceName: name,
      normalizedName: key,
      matchedTeacherId: null,
      matchedTeacherName: null,
      matchStatus: "unmatched" as const,
      aliases: [],
      teacherPeriodNotes: [],
      teacherPeriodNotesRaw: "",
      teacherPeriodNotesWarnings: [],
      records: [],
    };
    current.aliases = Array.from(new Set([...current.aliases, ...aliases]));
    if (freeText) {
      current.teacherPeriodNotesRaw = current.teacherPeriodNotesRaw
        ? current.teacherPeriodNotesRaw + "; " + freeText
        : freeText;
      const merged = new Map(current.teacherPeriodNotes.map((entry) => [entry.weekday + ":" + entry.period, entry]));
      for (const entry of parsedFree.periods) merged.set(entry.weekday + ":" + entry.period, entry);
      current.teacherPeriodNotes = Array.from(merged.values());
      current.teacherPeriodNotesWarnings = Array.from(new Set([...current.teacherPeriodNotesWarnings, ...parsedFree.warnings]));
    }
    imported.set(key, current);
  }

  for (const teacher of imported.values()) {
    const resolved = resolveSystemTeacher(teacher, systemTeachers);
    if (resolved.teacher) {
      const match = resolved.teacher;
      teacher.matchedTeacherId = String(match.id ?? match.name);
      teacher.matchedTeacherName = match.name;
      teacher.matchedDepartmentId = match.departmentId || match.departmentName || null;
      teacher.matchedDepartmentName = match.departmentName || match.departmentId || null;
      teacher.matchStatus = "matched";
    } else if (resolved.ambiguous) {
      teacher.matchStatus = "ambiguous";
    }
    for (const alias of teacher.aliases) {
      const key = normalizeArabicName(alias);
      if (!aliasMap.has(key)) aliasMap.set(key, new Set());
      aliasMap.get(key)!.add(teacher.normalizedName);
    }
  }
  return { teachers: Array.from(imported.values()), aliasMap };
}

function identifyTeacher(
  sourceName: string,
  directory: ImportedTeacher[],
): ImportedTeacher | null {
  const key = normalizeArabicName(sourceName);
  if (!key) return null;
  const matches = directory.filter((teacher) =>
    teacher.aliases.some((alias) => normalizeArabicName(alias) === key)
  );
  return matches.length === 1 ? matches[0] : null;
}

function parseLessonRows(
  sheetName: string,
  rows: CellValue[][],
  directory: ImportedTeacher[],
): { records: ImportedLessonRecord[]; unassigned: ImportedLessonRecord[]; placements: ImportedLessonRecord[] } {
  const objects = rowsToObjects(rows);
  const records: ImportedLessonRecord[] = [];
  const unassigned: ImportedLessonRecord[] = [];
  const placements: ImportedLessonRecord[] = [];
  let inheritedTeacher = "";
  let inheritedClass = "";

  for (const item of objects) {
    const values = item.values;
    const teacherCell = firstValue(values, ["المعلم", "المعلمون", "اسم المعلم"]);
    const classCell = firstValue(values, ["الشعب", "الشعبة", "الفصل", "الصف"]);
    const subject = normalizeSubjectName(firstValue(values, ["المادة", "اسم المادة"]));
    const group = firstValue(values, ["المجموعة", "التقسيم"]);
    const isTeacherHeader = !!teacherCell && !classCell && !subject;
    const isClassHeader = !!classCell && !teacherCell && !subject;

    if (isTeacherHeader) {
      inheritedTeacher = teacherCell;
      continue;
    }
    if (isClassHeader) {
      inheritedClass = classCell;
      continue;
    }

    const teacherName = teacherCell || inheritedTeacher;
    const className = classCell || inheritedClass;
    if (!teacherName && !className && !subject) continue;

    const day = normalizeSchoolWeekday(firstValue(values, ["اليوم", "يوم", "اليوم الدراسي"]));
    const periodText = firstValue(values, ["الحصة", "رقم الحصة", "الفترة", "رقم الفترة"]);
    const period = parseCount(periodText);
    const match = identifyTeacher(teacherName, directory);
    const record: ImportedLessonRecord = {
      id: `${normalizeArabicName(sheetName)}:${item.rowNumber}`,
      sourceSheet: sheetName,
      sourceRow: item.rowNumber,
      teacherSourceName: teacherName,
      teacherMatchStatus: match?.matchStatus || (teacherName ? "unmatched" : "unmatched"),
      className,
      groupName: group,
      subject,
      duration: firstValue(values, ["المدة", "مدة الحصة"]),
      periodsPerWeek: parseCount(valueByHeader(values, ["الحصص/الأسبوع", "الحصص الاسبوعية", "عدد الحصص"])),
      availableRooms: firstValue(values, ["الغرف الدراسية المتاحة", "الغرف المتاحة"]),
      cycle: firstValue(values, ["الدورة", "دورة"]),
      sharedTeachers: firstValue(values, ["معلم مشارك في المادة", "المعلم المشارك", "معلم مشارك"]),
      rooms: firstValue(values, ["الغرف الدراسية", "الغرفة"]),
      raw: { ...values },
      weekday: day,
      period: day && period !== null ? period : null,
    };
    records.push(record);
    if (match) match.records.push(record);
    else unassigned.push(record);
    if (record.weekday && record.period !== null) placements.push(record);
  }
  return { records, unassigned, placements };
}

export function parseTimetableWorkbook(
  sheets: WorkbookRows,
  systemTeachers: SystemTeacher[] = [],
): WorkbookImportResult {
  const warnings: string[] = [];
  const sourceSheets = Object.keys(sheets);
  const teacherSheet = findSheet(sheets, SHEET_ALIASES.teachers);
  const teacherRows = teacherSheet ? rowsToObjects(sheets[teacherSheet]) : [];
  const { teachers } = buildTeacherDirectory(teacherRows, systemTeachers);

  const validationErrors:string[]=[];
  if (!teacherSheet) { warnings.push("لم يتم العثور على ورقة المعلمين؛ ستحتاج مطابقة الأسماء يدوياً."); validationErrors.push("ورقة «المعلمون» مطلوبة لربط أسماء المعلمين والتحقق من هوياتهم."); }
  if (!findSheet(sheets, SHEET_ALIASES.lessons)) { warnings.push("لم يتم العثور على ورقة الحصص."); validationErrors.push("ورقة «الحصص» مطلوبة للتحقق من سجلات التدريس."); }
  if (!sourceSheets.length) validationErrors.push("ملف الجدول لا يحتوي على أوراق بيانات.");

  const referenceData: Record<string, ImportedReferenceRow[]> = {};
  if (teacherSheet) {
    // Preserve all teacher-level constraints (MWD, EXH, DAYS, <a,b>, availability notes, etc.)
    // verbatim so later scheduling rules can be defined without losing source data.
    referenceData[teacherSheet] = teacherRows.map((row) => ({
      sourceSheet: teacherSheet,
      sourceRow: row.rowNumber,
      values: row.values,
    }));
  }
  for (const [key, aliases] of Object.entries(SHEET_ALIASES)) {
    const sheetName = findSheet(sheets, aliases);
    if (!sheetName || key === "teachers" || key === "lessons" || key === "contracts" || key === "classContracts") continue;
    referenceData[sheetName] = rowsToObjects(sheets[sheetName]).map((row) => ({
      sourceSheet: sheetName,
      sourceRow: row.rowNumber,
      values: row.values,
    }));
  }

  const allRecords: ImportedLessonRecord[] = [];
  const unassignedRecords: ImportedLessonRecord[] = [];
  const placements: ImportedLessonRecord[] = [];
  for (const key of ["lessons", "contracts", "classContracts"] as const) {
    const sheetName = findSheet(sheets, SHEET_ALIASES[key]);
    if (!sheetName) continue;
    const parsed = parseLessonRows(sheetName, sheets[sheetName], teachers);
    allRecords.push(...parsed.records);
    unassignedRecords.push(...parsed.unassigned);
    placements.push(...parsed.placements);
  }

  // Keep every teacher name found in lesson/contract rows visible, even when
  // the workbook's teacher directory omitted it or the system has no match.
  const unresolvedRecords: ImportedLessonRecord[] = [];
  for (const record of unassignedRecords) {
    const key = normalizeArabicName(record.teacherSourceName);
    if (!key) {
      unresolvedRecords.push(record);
      continue;
    }
    const importedMatches = teachers.filter((item) => item.aliases.some((alias) => normalizeArabicName(alias) === key));
    if (importedMatches.length > 1) {
      const ambiguousTeacher: ImportedTeacher = {
        sourceName: record.teacherSourceName,
        normalizedName: key,
        matchedTeacherId: null,
        matchedTeacherName: null,
        matchStatus: "ambiguous",
        aliases: [record.teacherSourceName],
        teacherPeriodNotes: [],
        teacherPeriodNotesRaw: "",
        teacherPeriodNotesWarnings: [],
        records: [record],
      };
      teachers.push(ambiguousTeacher);
      record.teacherMatchStatus = "ambiguous";
      unresolvedRecords.push(record);
      continue;
    }
    let teacher = importedMatches[0] || null;
    if (!teacher) {
      const systemMatches = systemTeachers.filter((item) => normalizeArabicName(item.name) === key);
      const uniqueMatch = systemMatches.length === 1 ? systemMatches[0] : null;
      teacher = {
        sourceName: record.teacherSourceName,
        normalizedName: key,
        matchedTeacherId: uniqueMatch ? String(uniqueMatch.id ?? uniqueMatch.name) : null,
        matchedTeacherName: uniqueMatch?.name ?? null,
        matchStatus: uniqueMatch ? "matched" : systemMatches.length > 1 ? "ambiguous" : "unmatched",
        aliases: [record.teacherSourceName],
        teacherPeriodNotes: [],
        teacherPeriodNotesRaw: "",
        teacherPeriodNotesWarnings: [],
        records: [],
      };
      teachers.push(teacher);
    }
    teacher.records.push(record);
    record.teacherMatchStatus = teacher.matchStatus;
    if (teacher.matchStatus !== "matched") unresolvedRecords.push(record);
  }
  unassignedRecords.splice(0, unassignedRecords.length, ...unresolvedRecords);
  const unmatchedTeacherNames = teachers.filter((t) => t.matchStatus === "unmatched").map((t) => t.sourceName);
  const ambiguousTeacherNames = teachers.filter((t) => t.matchStatus === "ambiguous").map((t) => t.sourceName);
  if (!placements.length) {
    warnings.push("لم تُعثر على أعمدة واضحة لليوم ورقم الحصة؛ عُرضت بيانات العقود والحصص دون إنشاء جدول أسبوعي افتراضي.");
  }
  if (unmatchedTeacherNames.length) warnings.push(`يوجد ${unmatchedTeacherNames.length} اسم معلم يحتاج إلى مطابقة مع سجل النظام.`);
  if (ambiguousTeacherNames.length) warnings.push(`يوجد ${ambiguousTeacherNames.length} اسم معلم ملتبس يحتاج إلى مراجعة.`);

  return {
    schemaVersion: 1,
    sourceSheets,
    teachers,
    unmatchedTeacherNames,
    ambiguousTeacherNames,
    unassignedRecords,
    referenceData,
    placements,
    hasWeeklyPlacements: placements.length > 0,
    warnings,
    validation: { valid: validationErrors.length === 0, errors: validationErrors, warnings: [...warnings] },
    totals: {
      importedTeacherRows: teachers.length,
      importedLessonRecords: allRecords.length,
      referenceRows: Object.values(referenceData).reduce((sum, rows) => sum + rows.length, 0),
      placementRows: placements.length,
    },
  };
}

export interface ClassTimetableSourceCell {
  weekday: string; period: number; cell_status?: string; class_sections?: unknown;
  subject?: string | null; matched_teacher_name?: string | null; teacher_source_name?: string | null; source_group_note?: string | null;
}
export interface ClassTimetableSlot {
  weekday: string; period: number; subject: string; teacherName: string; status: string;
  coTeachingCount?: number; sourceGroupNote?: string;
}
export interface ClassTimetableSummary {
  className: string; expected: boolean; entries: ClassTimetableSlot[];
  vacancies: Array<{weekday:string;period:number}>;
  conflicts: Array<{weekday:string;period:number;assignments:ClassTimetableSlot[]}>;
  parallelGroups: Array<{weekday:string;period:number;assignments:ClassTimetableSlot[]}>;
  freePeriods: Array<{weekday:string;period:number}>;
  meetingPeriods: Array<{weekday:string;period:number}>;
  unclearPeriods: Array<{weekday:string;period:number}>;
  teachingCount: number; coveredCount: number; complete: boolean;
}
function key(value: unknown): string {
  return String(value ?? "").normalize("NFKC").replace(/[\u064b-\u065f\u0670\u0640]/g,"")
    .replace(/[أإآٱ]/g,"ا").replace(/ى/g,"ي").replace(/ة/g,"ه").replace(/\s+/g," ").trim();
}
function isPlaceholderClassName(value: string): boolean {
  const compact = value.normalize("NFKC").replace(/\s+/g, "");
  // Teacher-only free cells commonly use a dash instead of a class name.
  // These are not real class labels and must not create phantom class rows.
  return !compact || /^[-‐‑‒–—―−]+$/u.test(compact);
}
function classOrder(value: string): {grade:number;section:number} | null {
  const normalized=String(value||"").normalize("NFKC").replace(/[٠-٩]/g,d=>String("٠١٢٣٤٥٦٧٨٩".indexOf(d))).trim();
  const match=normalized.match(/^(\d+)\s*\/\s*(\d+)$/);
  if(!match)return null;
  const first=Number(match[1]),second=Number(match[2]);
  if(second>=9&&second<=12&&first>=1&&first<=12)return {grade:second,section:first};
  if(first>=9&&first<=12&&second>=1&&second<=12)return {grade:first,section:second};
  return {grade:second,section:first};
}
function compareClassNames(left:string,right:string):number {
  const a=classOrder(left),b=classOrder(right);
  if(a&&b)return a.grade-b.grade||a.section-b.section||left.localeCompare(right,"ar");
  if(a)return -1;
  if(b)return 1;
  return left.localeCompare(right,"ar");
}
function asciiDigits(value:string):string {
  return String(value||"").normalize("NFKC").replace(/[٠-٩]/g,d=>String("٠١٢٣٤٥٦٧٨٩".indexOf(d)));
}
export function classSectionsForCell(cell:ClassTimetableSourceCell):string[] {
  const raw=Array.isArray(cell.class_sections)?cell.class_sections:[];
  const sections=new Set<string>();
  for(const value of raw){
    for(const part of String(value||"").split(/[،,؛;]+/)){
      const section=asciiDigits(part).trim();
      if(section&&!isPlaceholderClassName(section))sections.add(section);
    }
  }
  if(String(cell.cell_status||"")!=="teaching")return Array.from(sections);
  // Legacy imports sometimes retained group class codes in the subject field
  // (e.g. 12/6 or 2/11/3/11) while class_sections kept only the first section.
  // Recover only codes in the same senior grade already attached to this cell.
  const grades=new Set(Array.from(sections).map(classOrder)
    .filter((v):v is {grade:number;section:number}=>!!v&&[11,12].includes(v.grade))
    .map(v=>v.grade));
  const subject=asciiDigits(String(cell.subject||""));
  for(const match of subject.matchAll(/(\d{1,2})\s*\/\s*(\d{1,2})/g)){
    const first=Number(match[1]),second=Number(match[2]);
    let grade=0,section=0;
    if([11,12].includes(first)&&second>=1&&second<=8){grade=first;section=second;}
    else if([11,12].includes(second)&&first>=1&&first<=8){grade=second;section=first;}
    if(grade&&grades.has(grade))sections.add(section+"/"+grade);
  }
  return Array.from(sections);
}
function isOptionalGroup(slot:ClassTimetableSlot):boolean {
  return key(slot.sourceGroupNote||"").includes("مجموعه ماده اختياريه");
}
function slotIdentity(slot: ClassTimetableSlot): string {
  return key(slot.status)+"|"+key(slot.subject);
}
/**
 * Build a class-first weekly audit. expectedClassNames comes from the school's
 * canonical classes table, so classes with no imported lessons are still audited.
 * A shared lesson (same class, period, teaching status and subject) is one class
 * slot even when multiple teachers are assigned to it.
 */
export function aggregateClassTimetables(
  cells: ClassTimetableSourceCell[],
  weekdays: string[],
  periodCount: number,
  expectedClassNames: string[] = [],
): ClassTimetableSummary[] {
  if (!Array.isArray(weekdays) || weekdays.length !== 5 || ![7,8].includes(periodCount)) {
    throw new Error("Invalid timetable dimensions");
  }
  const expected = new Set(expectedClassNames.map(value=>String(value||"").trim()).filter(Boolean));
  const classMap = new Map<string, Map<string, ClassTimetableSlot[]>>();
  for (const name of expected) classMap.set(name,new Map());
  for (const cell of cells || []) {
    if (!weekdays.includes(cell.weekday) || !Number.isInteger(Number(cell.period)) ||
        Number(cell.period)<1 || Number(cell.period)>periodCount) continue;
    const sections = classSectionsForCell(cell);
    for (const sectionValue of sections) {
      const className = String(sectionValue || "").trim();
      if (isPlaceholderClassName(className)) continue;
      if (!classMap.has(className)) classMap.set(className,new Map());
      const slots = classMap.get(className)!;
      const slotKey = cell.weekday + ":" + Number(cell.period);
      if (!slots.has(slotKey)) slots.set(slotKey,[]);
      slots.get(slotKey)!.push({
        weekday:cell.weekday, period:Number(cell.period), subject:String(cell.subject||""),
        teacherName:String(cell.matched_teacher_name||""),
        sourceGroupNote:String(cell.source_group_note||""),
        status:String(cell.cell_status||"unclear")==="teaching"&&!String(cell.subject||"").trim()?"unclear":String(cell.cell_status||"unclear"),
      });
    }
  }
  return Array.from(classMap.entries()).sort((a,b)=>compareClassNames(a[0],b[0])).map(([className,slots])=>{
    const entries:ClassTimetableSlot[]=[];
    const vacancies:Array<{weekday:string;period:number}>=[];
    const conflicts:Array<{weekday:string;period:number;assignments:ClassTimetableSlot[]}>= [];
    const parallelGroups:Array<{weekday:string;period:number;assignments:ClassTimetableSlot[]}>= [];
    const freePeriods:Array<{weekday:string;period:number}>=[];
    const meetingPeriods:Array<{weekday:string;period:number}>=[];
    const unclearPeriods:Array<{weekday:string;period:number}>=[];
    // Legacy active weeks may predate persistence of sourceGroupNote. Infer a
    // parallel elective pair only when the exact two-subject pair recurs once
    // on every weekday for this class; isolated or ambiguous double bookings
    // remain conflicts.
    const pairOccurrences=new Map<string,Map<string,number>>();
    for(const [slotKey,assignments] of slots.entries()){
      if(assignments.length!==2||!assignments.every(item=>item.status==="teaching"))continue;
      const pairKey=assignments.map(item=>key(item.subject)).sort().join("||");
      if(!pairKey||pairKey==="||")continue;
      const weekday=slotKey.slice(0,slotKey.lastIndexOf(":"));
      const dayCounts=pairOccurrences.get(pairKey)||new Map<string,number>();
      dayCounts.set(weekday,(dayCounts.get(weekday)||0)+1);
      pairOccurrences.set(pairKey,dayCounts);
    }
    const recurringElectivePairs=new Set<string>();
    for(const [pairKey,dayCounts] of pairOccurrences){
      if(weekdays.every(day=>dayCounts.get(day)===1))recurringElectivePairs.add(pairKey);
    }
    let teachingCount=0,coveredCount=0;
    for(const weekday of weekdays)for(let period=1;period<=periodCount;period++){
      const assignments=slots.get(weekday+":"+period)||[];
      const position={weekday,period};
      if(!assignments.length){vacancies.push(position);continue;}
      // Multiple teachers teaching the same subject to the same class at the
      // same time are co-teachers, not duplicate lessons or a timetable clash.
      const identities=new Set(assignments.map(slotIdentity));
      if(assignments.length>1 && identities.size>1){
        const pairKey=assignments.map(item=>key(item.subject)).sort().join("||");
        const explicitlyMarked=assignments.every(item=>item.status==="teaching"&&isOptionalGroup(item));
        const hasExplicitGroupMetadata=assignments.some(item=>String(item.sourceGroupNote||"").trim().length>0);
        const safelyInferred=assignments.length===2&&assignments.every(item=>item.status==="teaching")&&!hasExplicitGroupMetadata&&recurringElectivePairs.has(pairKey);
        if(explicitlyMarked||safelyInferred){
          parallelGroups.push({...position,assignments});
          coveredCount++;
          teachingCount++;
          continue;
        }
        conflicts.push({...position,assignments});
        coveredCount++;
        continue;
      }
      const first=assignments[0];
      const teacherNames=Array.from(new Set(assignments.map(item=>item.teacherName).filter(Boolean)));
      const entry:ClassTimetableSlot={
        ...first,
        teacherName:teacherNames.join("، "),
        ...(teacherNames.length>1?{coTeachingCount:teacherNames.length}:{})
      };
      entries.push(entry);
      coveredCount++;
      if(first.status!=="free"&&first.status!=="meeting"&&first.status!=="unclear")teachingCount++;
      else if(first.status==="free")freePeriods.push(position);
      else if(first.status==="meeting")meetingPeriods.push(position);
      else if(first.status==="unclear")unclearPeriods.push(position);
    }
    return {
      className,expected:expected.has(className),entries,vacancies,conflicts,parallelGroups,freePeriods,meetingPeriods,unclearPeriods,
      teachingCount,coveredCount,
      complete:vacancies.length===0&&conflicts.length===0&&unclearPeriods.length===0,
    };
  });
}

import { classSectionsForCell, type ClassTimetableSourceCell } from "./timetable_class_grid.ts";

export interface DutyReportCell extends ClassTimetableSourceCell {
  id?: string;
  matched_teacher_name?: string | null;
}
export interface DutyReportAssignment {
  assignment_type?: string;
  teacher_name?: string | null;
  absent_teacher_name?: string | null;
  source_cell_id?: string | null;
  class_sections?: unknown;
  status?: string;
}
export interface DutyReportLesson {
  teacherName: string;
  subject: string;
  substituteNames: string[];
}
export interface DutyReportClassContext {
  className: string;
  lessons: DutyReportLesson[];
}

function classIdentity(value: unknown): string {
  const normalized = String(value ?? "").normalize("NFKC")
    .replace(/[٠-٩]/g, digit => String("٠١٢٣٤٥٦٧٨٩".indexOf(digit)))
    .replace(/[\u064b-\u065f\u0670\u0640]/g, "")
    .replace(/[／⁄]/g, "/").replace(/\s+/g, "").trim();
  const pair = normalized.match(/^(\d+)\/(\d+)$/);
  if (!pair) return normalized;
  const first = Number(pair[1]), second = Number(pair[2]);
  if (second >= 9 && second <= 12) return second + "/" + first;
  if (first >= 9 && first <= 12) return first + "/" + second;
  return normalized;
}
// Match the canonical teacher identity rules used by timetable-management.
function teacherIdentity(value: unknown): string {
  return String(value ?? "").normalize("NFKC")
    .replace(/[\u064b-\u065f\u0670\u0640]/g, "")
    .replace(/[أإآٱ]/g, "ا").replace(/ى/g, "ي").replace(/ؤ/g, "و").replace(/ئ/g, "ي").replace(/ة/g, "ه")
    .replace(/\s+/g, "").trim();
}
function sections(value: unknown, subject = ""): string[] {
  return classSectionsForCell({
    weekday: "الأحد", period: 1, cell_status: "teaching",
    class_sections: value, subject,
  });
}
function unique(values: string[]): string[] {
  return [...new Set(values.map(value => String(value || "").trim()).filter(Boolean))];
}

/** Build class-specific lesson and substitute details from the active timetable. */
export function buildDutyReportContext(
  classNames: string[],
  cells: DutyReportCell[],
  assignments: DutyReportAssignment[],
): DutyReportClassContext[] {
  const activeAssignments = (assignments || []).filter(item =>
    item.assignment_type === "substitution" &&
    ["assigned", "confirmed", "completed"].includes(String(item.status || ""))
  );
  return (classNames || []).map(className => {
    const classKey = classIdentity(className);
    const lessonMap = new Map<string, DutyReportLesson>();
    for (const cell of cells || []) {
      if (cell.cell_status !== "teaching") continue;
      if (!sections(cell.class_sections, String(cell.subject || "")).some(value => classIdentity(value) === classKey)) continue;
      const teacherName = String(cell.matched_teacher_name || "").trim();
      const subject = String(cell.subject || "").trim();
      const lessonKey = teacherIdentity(teacherName) + "\u001f" + classIdentity(subject);
      let lesson = lessonMap.get(lessonKey);
      if (!lesson) {
        lesson = { teacherName, subject, substituteNames: [] };
        lessonMap.set(lessonKey, lesson);
      }
      if (!teacherName) continue;
      const substituteNames = [...lesson.substituteNames];
      for (const assignment of activeAssignments) {
        if (teacherIdentity(assignment.absent_teacher_name) !== teacherIdentity(teacherName)) continue;
        const sourceCellId = String(assignment.source_cell_id || "");
        if (sourceCellId && sourceCellId !== String(cell.id || "")) continue;
        const assignmentSections = sections(assignment.class_sections);
        if (assignmentSections.length && !assignmentSections.some(value => classIdentity(value) === classKey)) continue;
        if (!assignmentSections.length && !sourceCellId) continue;
        const substituteName = String(assignment.teacher_name || "").trim();
        if (substituteName) substituteNames.push(substituteName);
      }
      lesson.substituteNames = unique(substituteNames);
    }
    return {
      className,
      lessons: [...lessonMap.values()].map(lesson => ({
        ...lesson,
        substituteNames: unique(lesson.substituteNames),
      })),
    };
  });
}

export const DUTY_SCHOOL_DAYS = ["الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس"] as const;

type DutyPermissions = Record<string, unknown>;
type DutyPeriod = { start?: unknown; end?: unknown };

function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

function validDutyDay(value: unknown): value is string {
  return typeof value === "string" && (DUTY_SCHOOL_DAYS as readonly string[]).includes(value);
}

export function assignedDutyDay(
  permissionsValue: unknown,
  subjectDaysValue: unknown,
): string {
  const permissions: DutyPermissions = isRecord(permissionsValue) ? permissionsValue : {};
  const subjectDays = isRecord(subjectDaysValue) ? subjectDaysValue : {};
  // Match the application rule: an explicit personal duty day overrides category rotation.
  if (validDutyDay(permissions.dutyDay)) return permissions.dutyDay;
  const category = String(permissions.category || "").trim();
  const categoryDay = category ? subjectDays[category] : "";
  return validDutyDay(categoryDay) ? categoryDay : "";
}

/** A reporter is either directly granted duty access or a teacher assigned to today's duty day. */
export function isDutyReportEligibleOnDay(
  principalType: string,
  permissionsValue: unknown,
  subjectDaysValue: unknown,
  weekday: string,
): boolean {
  const permissions: DutyPermissions = isRecord(permissionsValue) ? permissionsValue : {};
  if (permissions.duty === true || permissions.admin === true) return true;
  if (principalType !== "teacher" || permissions.dutyToday === false) return false;
  return validDutyDay(weekday) && assignedDutyDay(permissions, subjectDaysValue) === weekday;
}

function omanDateParts(now: Date): { date: string; weekday: string; minutes: number } {
  const dateParts = new Intl.DateTimeFormat("en-CA", {
    timeZone: "Asia/Muscat",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const values = Object.fromEntries(dateParts.map((part) => [part.type, part.value]));
  const weekdayName = new Intl.DateTimeFormat("en-US", {
    timeZone: "Asia/Muscat",
    weekday: "long",
  }).format(now);
  const weekdays: Record<string, string> = {
    Sunday: "الأحد",
    Monday: "الاثنين",
    Tuesday: "الثلاثاء",
    Wednesday: "الأربعاء",
    Thursday: "الخميس",
    Friday: "الجمعة",
    Saturday: "السبت",
  };
  const timeParts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Asia/Muscat",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
  }).formatToParts(now);
  const timeValues = Object.fromEntries(timeParts.map((part) => [part.type, part.value]));
  return {
    date: String(values.year) + "-" + String(values.month).padStart(2, "0") + "-" + String(values.day).padStart(2, "0"),
    weekday: weekdays[weekdayName] || "",
    minutes: Number(timeValues.hour) * 60 + Number(timeValues.minute),
  };
}

function parseDutyTime(value: unknown): number | null {
  const match = /^([01]\d|2[0-3]):([0-5]\d)$/.exec(String(value || ""));
  return match ? Number(match[1]) * 60 + Number(match[2]) : null;
}

/**
 * Authorize the narrow timetable lookup for the active duty reporter.
 * Teachers assigned by personal dutyDay/category must request today's actual
 * period while it is open; explicit duty/admin grants retain the existing override.
 */
export function canReadDutyReportPeriod(input: {
  principalType: string;
  permissions: unknown;
  subjectDays: unknown;
  date: unknown;
  weekday: unknown;
  period: unknown;
  periods: unknown;
  graceMinutes: unknown;
  now?: Date;
}): boolean {
  const permissions: DutyPermissions = isRecord(input.permissions) ? input.permissions : {};
  if (permissions.duty === true || permissions.admin === true) return true;
  if (input.principalType !== "teacher" || permissions.dutyToday === false) return false;

  const now = input.now instanceof Date ? input.now : new Date();
  if (!Number.isFinite(now.getTime())) return false;
  const current = omanDateParts(now);
  const date = String(input.date || "").trim();
  const weekday = String(input.weekday || "").trim();
  const period = Number(input.period);
  if (date !== current.date || weekday !== current.weekday || !validDutyDay(weekday)) return false;
  if (assignedDutyDay(permissions, input.subjectDays) !== weekday) return false;
  if (!Number.isInteger(period) || period < 1 || period > 8) return false;

  const periods = Array.isArray(input.periods) ? input.periods : [];
  const selected = periods[period - 1] as DutyPeriod | undefined;
  if (!isRecord(selected)) return false;
  const start = parseDutyTime(selected.start);
  const end = parseDutyTime(selected.end);
  if (start === null || end === null || end <= start) return false;

  const rawGrace = Number(input.graceMinutes);
  const grace = Number.isFinite(rawGrace) ? Math.max(0, Math.min(30, rawGrace)) : 5;
  return current.minutes >= start + grace && current.minutes <= end;
}

export type TimetablePageResult<T> = {
  data: T[] | null;
  error: unknown;
};

/**
 * Read a PostgREST result in bounded pages. A stable ordering must be applied
 * by the caller before range(from, to) so no rows are skipped between pages.
 */
export async function fetchAllTimetablePages<T>(
  queryForRange: (from: number, to: number) => PromiseLike<TimetablePageResult<T>>,
  pageSize = 1000,
  maxRows = 25000,
): Promise<T[]> {
  if (!Number.isInteger(pageSize) || pageSize < 1 || !Number.isInteger(maxRows) || maxRows < pageSize) {
    throw new Error("Invalid timetable pagination limits");
  }
  const rows: T[] = [];
  for (let offset = 0; offset <= maxRows; offset += pageSize) {
    const { data, error } = await queryForRange(offset, offset + pageSize - 1);
    if (error) throw error;
    const page = Array.isArray(data) ? data : [];
    if (page.length === 0) return rows;
    if (rows.length + page.length > maxRows) {
      throw new Error("Weekly timetable exceeds the safe pagination limit");
    }
    rows.push(...page);
    if (page.length < pageSize) return rows;
  }
  return rows;
}

export const TEACHER_TIMETABLE_FALLBACK_FILTER =
  "matched_teacher_name.is.null,match_status.is.null,match_status.neq.matched";

export type TeacherTimetableCell = {
  matched_teacher_name?: unknown;
  teacher_source_name?: unknown;
  [key: string]: unknown;
};

/**
 * Combine indexed exact-name rows with legacy rows resolved through source names.
 * Exact-name rows are excluded from fallback to avoid duplicates.
 */
export function selectTeacherTimetableCells<T extends TeacherTimetableCell>(
  matchedRows: T[],
  fallbackRows: T[],
  teacherName: string,
  resolveName: (cell: T) => string | null,
): T[] {
  const fallback = fallbackRows.filter((cell) =>
    cell.matched_teacher_name !== teacherName && resolveName(cell) === teacherName
  );
  return [...matchedRows, ...fallback];
}

/** Availability rules for a complete, explicit weekly timetable grid. */
export interface SubstitutionTeacher {
  id:string; name:string; departmentId:string; weeklyQuota?:number;
  pointsBalance?:number; dailyTeachingCount?:number; dailySubstitutionCount?:number;
  substitutionsCount?:number; workloadScore?:number; historicalWorkloadScore?:number;
  proximityScore?:number; wouldCreateTriple?:boolean; occupiedPeriods?:number[];
}
export type TimetableCellStatus="teaching"|"free"|"meeting"|"activity"|"other"|"unclear";
export interface TimetableEntry { teacherId:string; weekday:string; period:number; className:string; subject?:string; status?:TimetableCellStatus; }
export interface SubstitutionAssignment {
  substituteTeacherId:string; absentTeacherId?:string; weekday:string; period:number;
  assignmentDate?:string|null; versionId?:string; assignmentType?:string;
  status?:"assigned"|"confirmed"|"cancelled"|"completed";
}
export interface SubstitutionLesson { weekday:string; period:number; className:string; subject?:string; }
export interface CandidateQuery {
  teachers:SubstitutionTeacher[]; timetable:TimetableEntry[]; assignments:SubstitutionAssignment[];
  absentTeacherId:string; weekday:string; period:number; departmentId:string; includeOtherDepartments?:boolean; otherDepartmentTeacherIds?:string[];
  assignmentDate?:string; versionId?:string; excludedTeacherIds?:string[]; maxDailySubstitutions?:number;
}
function sameCell(a:{weekday:string;period:number},b:{weekday:string;period:number}):boolean {
  return a.weekday===b.weekday && a.period===b.period;
}

/** School-approved points for a single substitute lesson (periods 1–8). */
export function getSubstitutionPeriodPoints(period:number):number {
  return ({1:1,2:1,3:2,4:2,5:4,6:3,7:5,8:7} as Record<number,number>)[period] ?? 0;
}

/** Strict ISO calendar-date validation; rejects normalized invalid dates such as February 30. */
export function isValidSubstitutionDate(value:unknown):value is string {
  if(typeof value!=="string"||!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed=new Date(value+"T00:00:00.000Z");
  return Number.isFinite(parsed.getTime())&&parsed.toISOString().slice(0,10)===value;
}

function assignmentBelongsToDate(
  assignment:SubstitutionAssignment, weekday:string, assignmentDate?:string, versionId?:string,
):boolean {
  if(assignment.weekday!==weekday) return false;
  if(assignmentDate && assignment.assignmentDate) return assignment.assignmentDate===assignmentDate;
  return !versionId || !assignment.versionId || assignment.versionId===versionId;
}

function hasThreeConsecutive(periods:Set<number>, target:number):boolean {
  const occupied=new Set(periods); occupied.add(target);
  for(let start=Math.max(1,target-2);start<=target;start++){
    if(occupied.has(start)&&occupied.has(start+1)&&occupied.has(start+2)) return true;
  }
  return false;
}
/** Only explicit teaching cells are lessons that need a replacement. */
export function getAbsentTeacherLessons(timetable:TimetableEntry[],teacherId:string,weekday:string):SubstitutionLesson[] {
  const byPeriod=new Map<number,{classNames:Set<string>;subjects:Set<string>}>();
  for(const entry of timetable.filter(e=>e.teacherId===teacherId&&e.weekday===weekday&&(e.status??"teaching")==="teaching")){
    const group=byPeriod.get(entry.period)??{classNames:new Set<string>(),subjects:new Set<string>()};
    if(entry.className)group.classNames.add(entry.className);
    if(entry.subject)group.subjects.add(entry.subject);
    byPeriod.set(entry.period,group);
  }
  return Array.from(byPeriod.entries()).sort((a,b)=>a[0]-b[0]).map(([period,group])=>({
    weekday,period,className:Array.from(group.classNames).join("، "),
    ...(group.subjects.size?{subject:Array.from(group.subjects).join("، ")}:{})
  }));
}

/** Counts distinct teacher/day/period teaching slots; shared-class duplicate rows count once. */
export function countTeacherTeachingPeriods(entries:TimetableEntry[]):Map<string,number> {
  const seen=new Set<string>();
  const counts=new Map<string,number>();
  for(const entry of entries){
    if(!entry.teacherId||!entry.weekday||(entry.status??"teaching")!=="teaching")continue;
    const key=entry.teacherId+"\\u0000"+entry.weekday+"\\u0000"+entry.period;
    if(seen.has(key))continue;
    seen.add(key);
    counts.set(entry.teacherId,(counts.get(entry.teacherId)||0)+1);
  }
  return counts;
}
/** Missing, duplicated, meeting, activity, other and unclear cells are never treated as free. */
export function getAvailableSubstitutionCandidates(query:CandidateQuery):SubstitutionTeacher[] {
  const {teachers,timetable,assignments,absentTeacherId,weekday,period,departmentId,includeOtherDepartments=false,otherDepartmentTeacherIds=[],assignmentDate,versionId,excludedTeacherIds=[],maxDailySubstitutions=2}=query;
  const cells=new Map<string,{count:number;isFree:boolean}>();
  for(const entry of timetable.filter(e=>sameCell(e,{weekday,period}))){
    const current=cells.get(entry.teacherId)??{count:0,isFree:true};
    current.count+=1;
    if((entry.status??"teaching")!=="free") current.isFree=false;
    cells.set(entry.teacherId,current);
  }
  const activeAssignments=assignments.filter(a=>a.status!=="cancelled");
  const assigned=new Set(activeAssignments.filter(a=>sameCell(a,{weekday,period})&&(assignmentDate&&a.assignmentDate? a.assignmentDate===assignmentDate : (!versionId||!a.versionId||a.versionId===versionId))).map(a=>a.substituteTeacherId));
  const historyFor=(teacherId:string)=>activeAssignments.filter(a=>
    a.substituteTeacherId===teacherId&&
    (a.assignmentType==="substitution"||!a.assignmentType)&&
    (!assignmentDate||!a.assignmentDate||a.assignmentDate<=assignmentDate)
  );
  const sameDayAssignments=(teacherId:string)=>activeAssignments.filter(a=>
    a.substituteTeacherId===teacherId &&
    (a.assignmentType==="substitution"||!a.assignmentType) &&
    assignmentBelongsToDate(a,weekday,assignmentDate,versionId)
  );
  const historicalScore=(history:SubstitutionAssignment[]):number=>
    calculateSubstitutionWorkloadScore(history,assignmentDate,period);
  const hasPointBalances=teachers.some(t=>typeof t.pointsBalance==="number");
  return teachers.filter(t=>t.id!==absentTeacherId&&!excludedTeacherIds.includes(t.id))
    .filter(t=>t.departmentId===departmentId||(includeOtherDepartments&&otherDepartmentTeacherIds.includes(t.id)))
    .filter(t=>{const cell=cells.get(t.id);return !!cell&&cell.count===1&&cell.isFree;})
    .filter(t=>!assigned.has(t.id)).map(t=>{
      const history=historyFor(t.id);
      const today=sameDayAssignments(t.id);
      const dailyTeachingPeriods=new Set(timetable.filter(e=>e.teacherId===t.id&&e.weekday===weekday&&(e.status??"teaching")==="teaching").map(e=>e.period));
      const teachingPeriods=new Set(dailyTeachingPeriods);
      for(const a of today) teachingPeriods.add(a.period);
      const dailyTeachingCount=dailyTeachingPeriods.size;
      const adjacent=teachingPeriods.has(period-1)||teachingPeriods.has(period+1);
      const triple=hasThreeConsecutive(teachingPeriods,period);
      const substitutionsCount=history.length;
      const dailySubstitutionCount=today.length;
      const weeklyQuota=Math.max(0,Number(t.weeklyQuota)||0);
      return {
        ...t,dailyTeachingCount,dailySubstitutionCount,substitutionsCount,
        occupiedPeriods:[...teachingPeriods].sort((a,b)=>a-b),
        proximityScore:adjacent?1:0,wouldCreateTriple:triple,
        workloadScore:weeklyQuota+substitutionsCount*2,
        historicalWorkloadScore:historicalScore(history),
      };
    })
    .filter(t=>(t.dailySubstitutionCount??0)<maxDailySubstitutions)
    .sort((a,b)=>{
      if(hasPointBalances){
        const points=(a.pointsBalance??0)-(b.pointsBalance??0);
        if(points!==0) return points;
        const dailySubs=(a.dailySubstitutionCount??0)-(b.dailySubstitutionCount??0);
        if(dailySubs!==0) return dailySubs;
        const weeklyLoad=(a.weeklyQuota??0)-(b.weeklyQuota??0);
        if(weeklyLoad!==0) return weeklyLoad;
        const dailyLoad=(a.dailyTeachingCount??0)-(b.dailyTeachingCount??0);
        if(dailyLoad!==0) return dailyLoad;
        const triple=Number(a.wouldCreateTriple)-Number(b.wouldCreateTriple);
        if(triple!==0) return triple;
        const proximity=(b.proximityScore??0)-(a.proximityScore??0);
        if(proximity!==0) return proximity;
      }
      return (a.workloadScore??0)-(b.workloadScore??0)||
        (a.historicalWorkloadScore??0)-(b.historicalWorkloadScore??0)||
        a.name.localeCompare(b.name,"ar");
    });
}


/**
 * Cumulative fairness score. Availability remains a hard gate; this score only
 * orders eligible teachers. Older assignments still count, while recent load
 * has greater influence to prevent repeatedly burdening the same teachers.
 */
export function calculateSubstitutionWorkloadScore(
  assignments:SubstitutionAssignment[],
  referenceDate?:string,
  targetPeriod?:number,
):number {
  const active=assignments.filter(a=>a.status!=="cancelled"&&(a.assignmentType==="substitution"||!a.assignmentType));
  const reference=referenceDate && /^\d{4}-\d{2}-\d{2}$/.test(referenceDate)
    ? new Date(referenceDate+"T12:00:00Z") : null;
  const dayMs=86400000;
  let total=0, last90=0, last30=0, last7=0, sameDay=0, adjacent=0;
  for(const assignment of active){
    if(reference && assignment.assignmentDate && /^\d{4}-\d{2}-\d{2}$/.test(assignment.assignmentDate)){
      const assignedAt=new Date(assignment.assignmentDate+"T12:00:00Z");
      const age=Math.floor((reference.getTime()-assignedAt.getTime())/dayMs);
      if(age<0) continue; // Future assignments must never affect a past/current fairness decision.
      total++;
      if(age<90) last90++;
      if(age<30) last30++;
      if(age<7) last7++;
      if(age===0) { sameDay++; if(targetPeriod && Math.abs(assignment.period-targetPeriod)===1) adjacent++; }
    } else {
      total++; // Undated legacy substitution rows remain part of cumulative history.
    }
  }
  // Total history prevents gaming by waiting out a short rolling window.
  return total + last90*2 + last30*3 + last7*4 + sameDay*8 + adjacent*4;
}

/** List only absent teachers the current coordinator is allowed to see. */
export function getVisibleAbsentTeachers(
  cells: Array<{ matchedTeacherName: string | null; status: string }>,
  directory: Array<{ name: string; role: string; departmentId: string }>,
  actorDepartmentId: string,
  isAdmin: boolean,
): string[] {
  const teachers = new Map(directory.map((teacher) => [teacher.name, teacher]));
  return Array.from(new Set(cells
    .filter((cell) => cell.status === "teaching" && !!cell.matchedTeacherName)
    .filter((cell) => {
      const teacher = teachers.get(cell.matchedTeacherName as string);
      return !!teacher && teacher.role === "teacher" &&
        (isAdmin || (!!actorDepartmentId && teacher.departmentId === actorDepartmentId));
    })
    .map((cell) => String(cell.matchedTeacherName))))
    .sort((a, b) => a.localeCompare(b, "ar"));
}


export interface BatchAbsentTeacher { id:string; name:string; departmentId:string; }
export interface BatchSubstitutionPlanQuery {
  teachers:SubstitutionTeacher[]; timetable:TimetableEntry[]; assignments:SubstitutionAssignment[];
  absentTeachers:BatchAbsentTeacher[]; weekday:string; assignmentDate:string; versionId:string;
  includeOtherDepartments?:boolean; otherDepartmentTeacherIds?:string[];
}
export interface BatchSubstitutionPlan {
  assignments:Array<{
    absentTeacherName:string; substituteTeacherName:string; weekday:string; period:number;
    className:string; subject?:string; points:number; pointsBalanceAfter:number; absentPointsBalanceAfter:number;
    substituteDailyTeachingCount:number; createsThreeConsecutive:boolean;
    candidateOptions:Array<{teacherName:string;pointsBalance:number;weeklyQuota:number;dailyTeachingCount:number;dailySubstitutionCount:number;occupiedPeriods:number[];adjacent:boolean;createsThreeConsecutive:boolean}>;
  }>;
  unassigned:Array<{absentTeacherName:string;weekday:string;period:number;className:string;subject?:string}>;
  assignedCount:number; unassignedCount:number;
}

/** Whole-morning allocator: one lesson per substitute first, two only if needed. */
export function buildBatchSubstitutionPlan(query:BatchSubstitutionPlanQuery):BatchSubstitutionPlan {
  const absentById=new Map(query.absentTeachers.map(t=>[t.id,t]));
  const excludedTeacherIds=Array.from(absentById.keys());
  // Preserve the coordinator's selected absent-teacher order. Finish every lesson
  // for the first absent teacher before moving to the next teacher.
  const orderedLessons=query.absentTeachers.flatMap(absent=>
    getAbsentTeacherLessons(query.timetable,absent.id,query.weekday)
      .sort((a,b)=>a.period-b.period)
      .map(lesson=>({absent,lesson}))
  );
  const simulatedAssignments=[...query.assignments];
  const mutableTeachers=query.teachers.map(t=>({...t,pointsBalance:Number(t.pointsBalance)||0}));
  const assignments:BatchSubstitutionPlan["assignments"]=[];
  const unassigned:BatchSubstitutionPlan["unassigned"]=[];
  for(const {absent,lesson} of orderedLessons){
    const alreadyAssigned=simulatedAssignments.some(a=>
      a.absentTeacherId===absent.id&&a.weekday===query.weekday&&a.period===lesson.period&&
      a.status!=="cancelled"&&assignmentBelongsToDate(a,query.weekday,query.assignmentDate,query.versionId)
    );
    if(alreadyAssigned) continue;
    const candidatesFor=(limit:number)=>getAvailableSubstitutionCandidates({
      teachers:mutableTeachers,timetable:query.timetable,assignments:simulatedAssignments,
      absentTeacherId:absent.id,weekday:query.weekday,period:lesson.period,
      departmentId:absent.departmentId,
      includeOtherDepartments:query.includeOtherDepartments===true,
      otherDepartmentTeacherIds:query.otherDepartmentTeacherIds??[],
      assignmentDate:query.assignmentDate,versionId:query.versionId,
      excludedTeacherIds,maxDailySubstitutions:limit,
    });
    const firstPass=candidatesFor(1);
    const allCandidates=candidatesFor(2);
    // Subject/department teachers always take priority. Cross-department
    // support is a fallback only when no eligible same-department teacher
    // can take the lesson within the one-per-day first pass.
    const sameDepartment=(candidate:SubstitutionTeacher)=>candidate.departmentId===absent.departmentId;
    const firstPassSameDepartment=firstPass.filter(sameDepartment);
    const firstPassOtherDepartments=firstPass.filter(candidate=>!sameDepartment(candidate));
    const allSameDepartment=allCandidates.filter(sameDepartment);
    const allOtherDepartments=allCandidates.filter(candidate=>!sameDepartment(candidate));
    const rankedCandidates=firstPassSameDepartment.length?firstPassSameDepartment:
      firstPassOtherDepartments.length?firstPassOtherDepartments:
      allSameDepartment.length?allSameDepartment:allOtherDepartments;
    // Keep the manual dropdown in the exact same priority tiers as automatic allocation:
    // same-department first cover, cross-department first cover, then second daily cover.
    // Each tier already carries the fairness ordering from getAvailableSubstitutionCandidates.
    const rankedOptions=[
      ...firstPassSameDepartment,
      ...firstPassOtherDepartments,
      ...allSameDepartment.filter(option=>(option.dailySubstitutionCount??0)>=1),
      ...allOtherDepartments.filter(option=>(option.dailySubstitutionCount??0)>=1),
    ];
    const candidate=rankedCandidates[0];
    if(!candidate){
      unassigned.push({absentTeacherName:absent.name,weekday:lesson.weekday,period:lesson.period,className:lesson.className,...(lesson.subject?{subject:lesson.subject}:{})});
      continue;
    }
    const points=getSubstitutionPeriodPoints(lesson.period);
    const teacher=mutableTeachers.find(t=>t.id===candidate.id)!;
    teacher.pointsBalance=(teacher.pointsBalance??0)+points;
    const absentTeacher=mutableTeachers.find(t=>t.id===absent.id);
    if(absentTeacher) absentTeacher.pointsBalance=(absentTeacher.pointsBalance??0)-points;
    assignments.push({
      absentTeacherName:absent.name,substituteTeacherName:candidate.name,weekday:lesson.weekday,
      period:lesson.period,className:lesson.className,...(lesson.subject?{subject:lesson.subject}:{}),
      points,pointsBalanceAfter:teacher.pointsBalance??0,absentPointsBalanceAfter:absentTeacher?.pointsBalance??0,
      substituteDailyTeachingCount:candidate.dailyTeachingCount??0,
      createsThreeConsecutive:candidate.wouldCreateTriple===true,
      candidateOptions:rankedOptions.map(option=>({
        teacherName:option.name,pointsBalance:option.pointsBalance??0,weeklyQuota:option.weeklyQuota??0,
        dailyTeachingCount:option.dailyTeachingCount??0,dailySubstitutionCount:option.dailySubstitutionCount??0,
        occupiedPeriods:option.occupiedPeriods??[],adjacent:option.proximityScore===1,
        createsThreeConsecutive:option.wouldCreateTriple===true,
      })),
    });
    simulatedAssignments.push({
      substituteTeacherId:candidate.id,absentTeacherId:absent.id,weekday:query.weekday,
      period:lesson.period,assignmentDate:query.assignmentDate,versionId:query.versionId,
      assignmentType:"substitution",status:"assigned",
    });
  }
  return {assignments,unassigned,assignedCount:assignments.length,unassignedCount:unassigned.length};
}

export type TimetablePrincipalType = "admin" | "teacher" | "custom";

export interface TimetablePrincipal {
  type: TimetablePrincipalType;
  name: string;
  /** A linked teacher with portal-only access; cannot manage timetables or substitutions. */
  portalOnly?: boolean;
  /** May view schoolwide reserve statistics; does not itself grant reserve management. */
  schoolwideReserveStats?: boolean;
  /** Has only the schoolwide reserve-statistics view, with no other timetable grant. */
  reserveStatsOnly?: boolean;
  /** Can only read the timetable context needed to compose an authorized duty report. */
  dutyReportOnly?: boolean;
  /** Current teacher reserve grant, read together with the teacher identity. */
  reserveAccess?: boolean;
  /** Current duty-report grant, checked only on the duty/report bootstrap actions. */
  dutyReportAccess?: boolean;
  /** Fresh permission snapshot loaded with the authenticated teacher record. */
  permissions?: Record<string, unknown>;
}

export interface TimetableSessionLookup {
  principal_type: unknown;
  principal_name: unknown;
  expires_at: unknown;
}

export interface TimetableTeacherLookup {
  name: string;
  role: string;
  reserveAccess?: boolean;
  permissions?: Record<string, unknown>;
}

export interface TimetableAuthStore {
  findSession(tokenHash: string, nowIso: string): Promise<TimetableSessionLookup | null>;
  hasAdminCredential(): Promise<boolean>;
  findTeacher(name: string, includePermissions?: boolean): Promise<TimetableTeacherLookup | null>;
  hasTimetableAccess(type: "teacher" | "custom", name: string): Promise<boolean>;
  hasDutyReportAccess?(type: "teacher" | "custom", name: string, permissions?: Record<string, unknown>, checkCurrentDay?: boolean): Promise<boolean>;
  canReadDutyReportContext?(type: "teacher" | "custom", name: string, date: string, weekday: string, period: number, permissions?: Record<string, unknown>): Promise<boolean>;
  hasLinkedTeacherPortalAccess?(name: string, action?: string): Promise<boolean>;
  /** Lightweight portal-setting check used only for the teacher's own daily notice. */
  hasSchoolwideReserveStatsAccess?(type: "teacher" | "custom", name: string): Promise<boolean>;
}

async function sha256(value: string): Promise<string> {
  const bytes = new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value)));
  return Array.from(bytes).map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

/**
 * Resolve a timetable identity only from a valid, active general-app session.
 * Staff management access requires an explicit timetable permission. A teacher
 * with a linked active schedule may receive a narrower, portal-only identity
 * when the school-wide teacher timetable portal is enabled. The caller never
 * supplies an identity name.
 */
export async function resolveTimetablePrincipal(
  authorization: unknown,
  store: TimetableAuthStore,
  now = Date.now(),
  requestedAction = "",
): Promise<TimetablePrincipal | null> {
  if (typeof authorization !== "string" || !Number.isFinite(now)) return null;
  const match = /^Bearer\s+([a-f0-9]{64})$/i.exec(authorization.trim());
  if (!match) return null;

  const tokenHash = await sha256(match[1].toLowerCase());
  const nowIso = new Date(now).toISOString();
  const session = await store.findSession(tokenHash, nowIso);
  if (!session || typeof session.expires_at !== "string") return null;
  const expiresAt = Date.parse(session.expires_at);
  if (!Number.isFinite(expiresAt) || expiresAt <= now) return null;

  if (session.principal_type === "admin" && session.principal_name === "مدير النظام العام") {
    return await store.hasAdminCredential()
      ? { type: "admin", name: "مدير النظام العام" }
      : null;
  }

  if (session.principal_type !== "teacher" && session.principal_type !== "custom") return null;
  if (typeof session.principal_name !== "string" || !session.principal_name.trim()) return null;

  const type = session.principal_type;
  const name = session.principal_name;
  const needsTeacherPermissions = requestedAction.startsWith("timetable_substitution_") ||
    new Set([
      "health",
      "timetable_check_access",
      "timetable_duty_report_context",
      "timetable_activity_report_data",
    ]).has(requestedAction);
  const teacher = await store.findTeacher(name, needsTeacherPermissions);
  if (!teacher || teacher.name !== name || teacher.role !== type) return null;
  const permissions = teacher.permissions && typeof teacher.permissions === "object"
    ? teacher.permissions : {};
  const reserveAccess = type === "teacher" && teacher.reserveAccess === true;
  // A dedicated report grant is read-only and authorizes only the all-school reserve report action.
  if (requestedAction === "timetable_substitution_report" &&
      type === "teacher" && permissions.reportSubstitutionDistribution === true) {
    return { type, name, permissions };
  }
  // These two reads are strictly self-scoped by their request handlers. The
  // handlers verify the live portal allow-list or query only this teacher's
  // assignments, so preflight permission/portal queries here are redundant.
  if (type === "teacher" && new Set([
    "teacher_timetable_get_own",
    "teacher_substitution_get_today",
  ]).has(requestedAction)) {
    return { type, name, portalOnly: true };
  }
  // The schoolwide statistics grant is relevant only to the statistics action.
  // Avoid one permission-table read on every unrelated timetable request.
  const needsSchoolwideReserveStats = new Set([
    "timetable_substitution_stats",
    // Statistics-only accounts historically retain these narrow bootstrap/read actions.
    "health",
    "timetable_check_access",
  ]).has(requestedAction);
  const hasSchoolwideReserveStats = async () => needsSchoolwideReserveStats &&
    store.hasSchoolwideReserveStatsAccess
      ? await store.hasSchoolwideReserveStatsAccess(type, name)
      : false;
  const dutyReportAction = requestedAction === "timetable_duty_report_context";
  if (await store.hasTimetableAccess(type, name)) {
    const schoolwideReserveStats = await hasSchoolwideReserveStats();
    const dutyReportAccess = dutyReportAction && store.hasDutyReportAccess
      ? await store.hasDutyReportAccess(type, name, permissions, requestedAction !== "timetable_duty_report_context")
      : false;
    return {
      type, name, permissions, reserveAccess, schoolwideReserveStats,
      ...(dutyReportAction ? { dutyReportAccess } : {}),
    };
  }
  // Reserve permission is loaded with the teacher identity, avoiding a second
  // teachers-table read during authorization and again in the request handler.
  if (reserveAccess) {
    const schoolwideReserveStats = await hasSchoolwideReserveStats();
    const dutyReportAccess = dutyReportAction && store.hasDutyReportAccess
      ? await store.hasDutyReportAccess(type, name, permissions, requestedAction !== "timetable_duty_report_context")
      : false;
    return {
      type, name, permissions, reserveAccess: true, schoolwideReserveStats,
      ...(dutyReportAction ? { dutyReportAccess } : {}),
    };
  }
  const schoolwideReserveStats = await hasSchoolwideReserveStats();
  if (schoolwideReserveStats) {
    return { type, name, schoolwideReserveStats: true, reserveStatsOnly: true };
  }
  // The daily notice exposes only this teacher's own assignments. For this
  // action, verify the configured portal allow-list without loading weekly cells.
  if (type === "teacher" && new Set([
    "health",
    "timetable_check_access",
  ]).has(requestedAction)) {
    // Full linked-schedule verification is needed only for portal status reads.
    if (store.hasLinkedTeacherPortalAccess
      && await store.hasLinkedTeacherPortalAccess(name, requestedAction)) {
      return { type, name, portalOnly: true };
    }
  }
  const mayUseDutyBootstrap = new Set([
    "health",
    "timetable_check_access",
    "teacher_substitution_get_today",
  ]).has(requestedAction);
  if ((dutyReportAction || mayUseDutyBootstrap) && store.hasDutyReportAccess
    && await store.hasDutyReportAccess(type, name, permissions, requestedAction !== "timetable_duty_report_context")) {
    return { type, name, permissions, dutyReportOnly: true, dutyReportAccess: true };
  }
  return null;
}


/** Actions available to an explicitly authorized non-admin timetable account. */
export function canUseTimetableAction(
  principalType: TimetablePrincipalType,
  action: string,
  portalOnly = false,
  hasReservePermission = false,
  reserveStatsOnly = false,
  schoolwideReserveStats = false,
  dutyReportOnly = false,
): boolean {
  if (principalType === "admin") return true;
  if (dutyReportOnly) return new Set(["health", "timetable_check_access", "timetable_duty_report_context", "teacher_substitution_get_today"]).has(action);
  if (schoolwideReserveStats && action === "timetable_substitution_stats") return true;
  if (portalOnly) return new Set([
    "health",
    "timetable_check_access",
    "teacher_timetable_get_own",
    "teacher_substitution_get_today",
  ]).has(action);
  if (reserveStatsOnly) return new Set([
    "health",
    "timetable_check_access",
    "timetable_substitution_stats",
  ]).has(action);
  const substitutionActions = new Set([
    "timetable_substitution_preview",
    "timetable_substitution_departments",
    "timetable_substitution_save",
    "timetable_substitution_cancel",
    "timetable_substitution_cancel_batch",
    "timetable_substitution_batch_preview",
    "timetable_substitution_batch_save",
    "timetable_substitution_stats",
    "timetable_substitution_archive",
    "timetable_substitution_update",
    "timetable_substitution_update_batch",
    "timetable_substitution_reset_options",
    "timetable_substitution_reset",
  ]);
  if (principalType === "teacher") {
    if (substitutionActions.has(action)) return hasReservePermission;
    return new Set(["health","timetable_check_access","teacher_timetable_get_own","teacher_substitution_get_today"]).has(action);
  }
  const customSubstitutionActions = new Set([
    "timetable_substitution_preview",
    "timetable_substitution_save",
    "timetable_substitution_cancel",
    "timetable_substitution_cancel_batch",
  ]);
  return new Set([
    "health",
    "timetable_check_access",
    "teacher_timetable_get_own",
    ...customSubstitutionActions,
  ]).has(action);
}

/** The administrator or a teacher explicitly granted reserve-distribution permission may broaden substitute candidates. */
export function canIncludeOtherDepartments(
  principalType: TimetablePrincipalType, requested: unknown, hasReservePermission = false,
): boolean {
  return requested === true && (principalType === "admin" || (principalType === "teacher" && hasReservePermission));
}

export function canAccessTeacherTimetablePortal(enabled: unknown, selectedTeacherNames: unknown, teacherName: string): boolean {
  if (enabled !== true || !String(teacherName || "").trim()) return false;
  const selected = Array.isArray(selectedTeacherNames)
    ? selectedTeacherNames.map((value) => String(value || "").trim()).filter(Boolean)
    : [];
  return selected.length === 0 || selected.includes(String(teacherName).trim());
}
